	get_credit_limit_customer_export_bundle(customer) {
		if (!this.credit_limit_insights || !customer) {
			return Promise.resolve(null);
		}

		const record = this.credit_limit_insights.records.find((item) => item.customer === customer);
		if (!record) {
			return Promise.resolve(null);
		}

		const creditRows = (record.credit_limit_rows || []).length
			? record.credit_limit_rows
			: [{ company: this.filters.company, credit_limit: record.credit_limit || 0, credit_limit_days: record.credit_limit_days || 0 }];
		const openInvoices = [...(record.invoices || [])]
			.filter((invoice) => (invoice.outstanding || 0) > 0)
			.sort((left, right) => {
				if ((right.outstanding || 0) !== (left.outstanding || 0)) {
					return (right.outstanding || 0) - (left.outstanding || 0);
				}
				return (right.age || 0) - (left.age || 0);
			});

			return this.fetch_credit_limit_customer_payment_followup(customer, record.customer_name || record.customer).then((followups) => ({
			record,
			creditRows,
			openInvoices,
			followups: Array.isArray(followups) ? followups : []
		}));
	}

	sanitize_export_filename(value) {
		return (value || 'customer')
			.toString()
			.trim()
			.replace(/[^a-z0-9]+/gi, '_')
			.replace(/^_+|_+$/g, '') || 'customer';
	}

	download_text_file(content, filename, mimeType = 'text/plain;charset=utf-8;') {
		const blob = new Blob([content], { type: mimeType });
		const link = document.createElement('a');
		const url = URL.createObjectURL(blob);
		link.href = url;
		link.download = filename;
		link.style.visibility = 'hidden';
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);
		setTimeout(() => URL.revokeObjectURL(url), 1000);
	}

	download_base64_file(base64Content, filename, mimeType = 'application/octet-stream') {
		const binary = atob(base64Content || '');
		const bytes = new Uint8Array(binary.length);
		for (let index = 0; index < binary.length; index += 1) {
			bytes[index] = binary.charCodeAt(index);
		}

		const blob = new Blob([bytes], { type: mimeType });
		const link = document.createElement('a');
		const url = URL.createObjectURL(blob);
		link.href = url;
		link.download = filename;
		link.style.visibility = 'hidden';
		document.body.appendChild(link);
		link.click();
		document.body.removeChild(link);
		setTimeout(() => URL.revokeObjectURL(url), 1000);
	}

