		const effColor = (safeSummary.collection_efficiency || 0) >= 80 ? '#10b981' : (safeSummary.collection_efficiency || 0) >= 50 ? '#f59e0b' : '#f87171';
		const effBg = (safeSummary.collection_efficiency || 0) >= 80 ? 'rgba(16,185,129,0.12)' : (safeSummary.collection_efficiency || 0) >= 50 ? 'rgba(245,158,11,0.12)' : 'rgba(248,113,113,0.12)';
		const effBorder = (safeSummary.collection_efficiency || 0) >= 80 ? 'rgba(16,185,129,0.28)' : (safeSummary.collection_efficiency || 0) >= 50 ? 'rgba(245,158,11,0.28)' : 'rgba(248,113,113,0.28)';

