		load_credit_limit_customer_payment_followup($wrapper, customer, customerName = '') {
			if (!$wrapper || !$wrapper.length) {
				return;
			}

			$wrapper.html(`
				<div class="section-card" style="padding: 18px; margin-top: 16px;">
					<h4 style="margin: 0 0 12px 0; color: #e2e8f0;">Payment Follow-up</h4>
					<div style="color: #94a3b8;"><i class="fa fa-spinner fa-spin"></i> Loading payment follow-up data...</div>
				</div>
			`);

			this.fetch_credit_limit_customer_payment_followup(customer, customerName)
				.then((items) => {
					$wrapper.html(this.render_credit_limit_payment_followup_section(items));
				})
				.catch(() => {
					$wrapper.html(`
						<div class="section-card" style="padding: 18px; margin-top: 16px;">
							<h4 style="margin: 0 0 12px 0; color: #e2e8f0;">Payment Follow-up</h4>
							<div style="color: #fca5a5;">Unable to load payment follow-up data for this customer.</div>
						</div>
					`);
				});
		}

		bind_payment_followup_history_events() {
			const $tableContainer = this.main_container.find('.payment-followup-table');
			$tableContainer.off('click', '.payment-followup-toggle-history');
			$tableContainer.on('click', '.payment-followup-toggle-history', function() {
			const $button = $(this);
			const targetId = $button.data('target');
			const $targetRow = $('#' + targetId);
			const isOpen = $targetRow.is(':visible');

			$targetRow.toggle(!isOpen);
			$button.attr('aria-expanded', isOpen ? 'false' : 'true');
			$button.find('i').attr('class', isOpen ? 'fa fa-chevron-down' : 'fa fa-chevron-up');
			$button.find('.toggle-label').text(isOpen ? 'View History' : 'Hide History');
		});
	}

