	create_aging_pie_chart() {
		const ctx = document.getElementById('aging-pie-chart');
		if (!ctx) return;

		this.aging_pie_chart = new Chart(ctx, {
			type: 'doughnut',
			data: {
				labels: ['0-30 Days', '31-60 Days', '61-90 Days', 'Over 90 Days'],
				datasets: [{
					data: [0, 0, 0, 0],
					backgroundColor: ['#10b981', '#f59e0b', '#ef4444', '#dc2626'],
					borderWidth: 2,
					borderColor: '#ffffff'
				}]
			},
			options: {
				responsive: true,
				maintainAspectRatio: false,
				plugins: {
					legend: {
						position: 'bottom',
						labels: {
							padding: 20,
							usePointStyle: true
						}
					},
					tooltip: {
						callbacks: {
							label: function (context) {
								const label = context.label || '';
								const value = context.parsed || 0;
								const total = context.dataset.data.reduce((a, b) => a + b, 0);
								const percentage = total > 0 ? ((value / total) * 100).toFixed(1) : 0;
								return `${label}: AED ${value.toLocaleString()} (${percentage}%)`;
							}
						}
					}
				}
			}
		});
	}

	create_payment_trends_chart() {
		const ctx = document.getElementById('payment-trends-chart');
		if (!ctx) return;

		const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
		const currentMonth = new Date().getMonth();
		const last6Months = [];
		for (let i = 5; i >= 0; i--) {
			const monthIndex = (currentMonth - i + 12) % 12;
			last6Months.push(months[monthIndex]);
		}

		this.payment_trends_chart = new Chart(ctx, {
			type: 'line',
			data: {
				labels: last6Months,
				datasets: [{
					label: 'Payments Received',
					data: [0, 0, 0, 0, 0, 0],
					borderColor: '#10b981',
					backgroundColor: 'rgba(16, 185, 129, 0.1)',
					tension: 0.4,
					fill: true
				}]
			},
			options: {
				responsive: true,
				maintainAspectRatio: false,
				plugins: {
					legend: {
						display: true,
						position: 'top'
					}
				},
				scales: {
					y: {
						beginAtZero: true,
						ticks: {
							callback: function (value) {
								return 'AED ' + value.toLocaleString();
							}
						}
					}
				}
			}
		});
	}

